-- Mock 2 of each subject is exclusive: it lives only in the database and is
-- shown only to accounts listed in mock_access. Run once in the SQL Editor.

insert into public.mocks (id, title, minutes, total, is_public, questions)
values ('math2', 'Mathematics Mock 2', 60, 30, false,
$json$[{"q": "Simplify (√7 + √3)/(√7 − √3) + (√7 − √3)/(√7 + √3).", "options": ["5/2", "√21", "(5 + √21)/2", "5", "2√21", "5 + √21", "10", "20"], "answer": 3, "topic": "M2 Number", "marks": 4, "solutionImage": "solutions/m2-q01.jpg"}, {"q": "A wooden block measures 20 cm by 10 cm by 4 cm. The wood has a density of 0.65 g/cm^{3}.\nWhat is the mass of the block, in kg?", "options": ["0.13", "0.52", "0.65", "1.3", "2.6", "5.2", "52", "520"], "answer": 1, "topic": "M1 Units", "marks": 2, "solutionImage": "solutions/m2-q02.jpg"}, {"q": "How many integers from 1 to 600 inclusive are divisible by 4 or by 6, but are not divisible by 9?", "options": ["134", "150", "159", "164", "167", "184", "200", "216"], "answer": 4, "topic": "M2 Number", "marks": 8, "solutionImage": "solutions/m2-q03.jpg"}, {"q": "By writing x^{2} − 6x + 14 in the form (x − p)^{2} + q, find the greatest value of 12/(x^{2} − 6x + 14).", "options": ["6/7", "1", "4/3", "2", "12/5", "3", "4", "12"], "answer": 4, "topic": "M4 Algebra", "marks": 5, "solutionImage": "solutions/m2-q04.jpg"}, {"q": "Write 0.0040596 correct to 3 significant figures.", "options": ["0.004", "0.00405", "0.00406", "0.0041", "0.0046", "0.0406", "0.406", "4.06"], "answer": 2, "topic": "M2 Number", "marks": 1, "solutionImage": "solutions/m2-q05.jpg"}, {"q": "A ball is dropped from a height of 8 m onto horizontal ground. After each bounce it rises to 3/4 of the height from which it last fell.\nFind the total distance the ball has travelled, in metres, at the moment it hits the ground for the 4th time.", "options": ["21.875", "24", "27.75", "29", "32", "34", "35.75", "40.8125"], "answer": 6, "topic": "M3 Ratio and proportion", "marks": 7, "solutionImage": "solutions/m2-q06.jpg"}, {"q": "Three lights flash every 18 seconds, 30 seconds and 45 seconds respectively. They all flash together at exactly 21:00.\nHow many times do all three flash together after 21:00, up to and including 22:00?", "options": ["18", "20", "30", "36", "39", "40", "41", "80"], "answer": 5, "topic": "M2 Number", "marks": 3, "solutionImage": "solutions/m2-q07.jpg"}, {"q": "PA and PB are tangents to the circle with centre O, touching it at A and B. Angle APB = 50°.\nC lies on the major arc AB and D lies on the minor arc AB.\nFind angle ADB.", "image": "images/math2-q8.png", "alt": "Circle with centre O, tangents PA and PB meeting at P with angle 50 degrees. C is on the major arc and D on the minor arc.", "options": ["25°", "40°", "50°", "65°", "90°", "100°", "105°", "115°"], "answer": 7, "topic": "M5 Geometry", "marks": 6, "solutionImage": "solutions/m2-q08.jpg"}, {"q": "How many ordered pairs (m, n) of positive integers satisfy 1/m + 1/n = 1/6?", "options": ["4", "5", "8", "9", "10", "12", "18", "36"], "answer": 3, "topic": "M2 Number", "marks": 11, "solutionImage": "solutions/m2-q09.jpg"}, {"q": "Two statues are mathematically similar. Their volumes are 216 cm^{3} and 729 cm^{3}.\nExactly 80 ml of paint covers the surface of the smaller statue. How much paint, in ml, is needed for the larger statue?", "options": ["120", "180", "200", "240", "270", "320", "360", "405"], "answer": 1, "topic": "M3 Ratio and proportion", "marks": 5, "solutionImage": "solutions/m2-q10.jpg"}, {"q": "15 000 tenge is invested at 4% per year simple interest. After how many years is it worth 19 200 tenge?", "options": ["4", "5", "6", "7", "8", "9", "10", "12"], "answer": 3, "topic": "M3 Ratio and proportion", "marks": 2, "solutionImage": "solutions/m2-q11.jpg"}, {"q": "A rectangle has a perimeter of 34 cm and a diagonal of length 13 cm.\nFind the area of the rectangle, in cm^{2}.", "options": ["30", "34", "40", "45", "52", "56", "60", "120"], "answer": 6, "topic": "M4 Algebra", "marks": 6, "solutionImage": "solutions/m2-q12.jpg"}, {"q": "From a port P, ship A is 5 km away on a bearing of 040° and ship B is 5√3 km away on a bearing of 130°.\nFind the bearing of B from A.", "options": ["040°", "070°", "100°", "130°", "140°", "160°", "200°", "220°"], "answer": 5, "topic": "M5 Geometry", "marks": 8, "solutionImage": "solutions/m2-q13.jpg"}, {"q": "2/5 of a number A is equal to 3/4 of a number B, and A − B = 21.\nFind A + B.", "options": ["39", "45", "48", "51", "57", "63", "66", "69"], "answer": 7, "topic": "M3 Ratio and proportion", "marks": 4, "solutionImage": "solutions/m2-q14.jpg"}, {"q": "Triangle ABC has a right angle at C, with CA = 8 cm and CB = 15 cm.\nA large circle touches all three sides of the triangle. A small circle touches CA, CB and the large circle, as shown.\nFind the radius of the small circle, in cm.", "image": "images/math2-q15.png", "alt": "Right-angled triangle with CA 8 and CB 15, a large circle touching all three sides and a small circle in the corner at C.", "options": ["3 − 2√2", "9 − 6√2", "3(√2 − 1)/2", "2√2 − 2", "(6 − 3√2)/2", "1", "3√2 − 3", "6 − 3√2"], "answer": 1, "topic": "M5 Geometry", "marks": 12, "solutionImage": "solutions/m2-q15.jpg"}, {"q": "The price of a phone is increased by 30%. The new price is then reduced by 30%. The final price is 18 200 tenge.\nWhat was the original price, in tenge?", "options": ["18 200", "19 110", "20 000", "20 200", "21 000", "23 660", "26 000", "28 000"], "answer": 2, "topic": "M3 Ratio and proportion", "marks": 3, "solutionImage": "solutions/m2-q16.jpg"}, {"q": "The curve y = ka^{x}, where a > 0, passes through the points (1, 6) and (3, 54).\nFind the value of y when x = −1.", "options": ["2/3", "1", "3/2", "2", "3", "6", "9", "18"], "answer": 0, "topic": "M4 Algebra", "marks": 5, "solutionImage": "solutions/m2-q17.jpg"}, {"q": "Triangle T has vertices (1, 1), (4, 1) and (1, 3).\nT is reflected in the line y = x. The image is then rotated 90° clockwise about the origin O.\nWhich single transformation maps T onto the final image?", "image": "images/math2-q18.png", "alt": "Triangle T on a grid with vertices (1, 1), (4, 1) and (1, 3).", "options": ["rotation 90° anticlockwise about O", "rotation 90° clockwise about O", "rotation 180° about O", "reflection in the line y = x", "reflection in the line y = −x", "reflection in the x-axis", "reflection in the y-axis"], "answer": 5, "topic": "M5 Geometry", "marks": 6, "solutionImage": "solutions/m2-q18.jpg"}, {"q": "The length L cm of a rod is 7.4 cm when truncated to 1 decimal place.\nWhich is the error interval for L?", "options": ["7.35 ≤ L < 7.45", "7.4 ≤ L < 7.5", "7.4 < L ≤ 7.5", "7.35 < L ≤ 7.45", "7.3 < L ≤ 7.4", "7.4 ≤ L ≤ 7.5", "7.45 ≤ L < 7.55"], "answer": 1, "topic": "M2 Number", "marks": 2, "solutionImage": "solutions/m2-q19.jpg"}, {"q": "ABCD is a trapezium with AB parallel to DC, AB = 6 cm and DC = 15 cm.\nThe diagonals AC and BD meet at X.\nThe area of triangle ABX is 8 cm^{2}. Find the area of the trapezium, in cm^{2}.", "image": "images/math2-q20.png", "alt": "Trapezium ABCD with AB 6 cm and DC 15 cm. Diagonals meet at X and triangle ABX is shaded with area 8.", "options": ["50", "58", "66", "70", "78", "84", "90", "98"], "answer": 7, "topic": "M5 Geometry", "marks": 10, "solutionImage": "solutions/m2-q20.jpg"}, {"q": "Simplify fully 3/(x − 2) − 2/(x + 1) − 9/[(x − 2)(x + 1)].", "options": ["1/(x − 2)", "(x − 2)/(x + 1)", "1/[(x − 2)(x + 1)]", "1/(x + 1)", "(x − 10)/[(x − 2)(x + 1)]", "(x + 10)/[(x − 2)(x + 1)]", "(x + 1)/(x − 2)", "3/(x + 1)"], "answer": 3, "topic": "M4 Algebra", "marks": 5, "solutionImage": "solutions/m2-q21.jpg"}, {"q": "The region R is defined by the inequalities y ≥ 1, x + y ≤ 6 and y ≤ 2x. It is shaded in the diagram.\nHow many points with integer coordinates lie in R, including points on its boundary?", "image": "images/math2-q22.png", "alt": "Shaded region R bounded by y = 1, x + y = 6 and y = 2x.", "options": ["6", "7", "8", "9", "10", "11", "12", "13"], "answer": 6, "topic": "M4 Algebra", "marks": 7, "solutionImage": "solutions/m2-q22.jpg"}, {"q": "An alloy is made by melting together 300 cm^{3} of metal P, of density 8 g/cm^{3}, and V cm^{3} of metal Q, of density 11 g/cm^{3}.\nThe volume of the alloy equals the total volume of the two metals, and its density is 9.2 g/cm^{3}. Find V.", "options": ["200", "225", "240", "250", "300", "360", "450", "600"], "answer": 0, "topic": "M1 Units", "marks": 6, "solutionImage": "solutions/m2-q23.jpg"}, {"q": "Solve 9^{x + 1} = 27^{2x − 1} / 3^{x}.", "options": ["1/3", "1", "5/4", "4/3", "5/3", "2", "5/2", "3"], "answer": 4, "topic": "M2 Number", "marks": 4, "solutionImage": "solutions/m2-q24.jpg"}, {"q": "A sector of a circle has a perimeter of 28 cm and an area of 49 cm^{2}.\nFind the radius of the circle, in cm.", "options": ["5", "6", "7", "8", "9", "10", "12", "14"], "answer": 2, "topic": "M5 Geometry", "marks": 9, "solutionImage": "solutions/m2-q25.jpg"}, {"q": "12 identical machines working together can complete a job in 15 hours. All 12 machines start the job, but after 5 hours, 4 of them break down. The remaining machines finish the job.\nHow many hours does the whole job take?", "options": ["20", "22.5", "24", "25", "27", "30", "35", "45"], "answer": 0, "topic": "M3 Ratio and proportion", "marks": 5, "solutionImage": "solutions/m2-q26.jpg"}, {"q": "Solve 5 − 3x > 2x − 10.", "options": ["x < −3", "x > −3", "x < 3", "x > 3", "x < 5", "x > 5", "x < 15", "x > 15"], "answer": 2, "topic": "M4 Algebra", "marks": 2, "solutionImage": "solutions/m2-q27.jpg"}, {"q": "ABCDEFGH is a cuboid. The base ABCD has AB = 3 cm and BC = 4 cm, and the vertical edge AE = 5√3 cm.\nFind the angle between the diagonal AG and the base ABCD.", "image": "images/math2-q28.png", "alt": "Cuboid ABCDEFGH with AB 3 cm, BC 4 cm, AE 5 root 3 cm and diagonal AG drawn.", "options": ["10°", "15°", "20°", "30°", "45°", "60°", "75°", "90°"], "answer": 5, "topic": "M5 Geometry", "marks": 6, "solutionImage": "solutions/m2-q28.jpg"}, {"q": "Find the exact value of sin 300° × cos 150° + tan 225°.", "options": ["−7/4", "−1/4", "1/4", "3/4", "1", "5/4", "7/4", "2"], "answer": 6, "topic": "M4 Algebra", "marks": 5, "solutionImage": "solutions/m2-q29.jpg"}, {"q": "A is the point (−1, 3) and B is the point (5, 7).\nThe perpendicular bisector of AB crosses the x-axis at the point Q. Find the coordinates of Q.", "options": ["(16/3, 0)", "(10/3, 0)", "(−4/3, 0)", "(−11/2, 0)", "(0, 8)", "(2, 0)", "(19/3, 0)", "(0, 16/3)"], "answer": 0, "topic": "M4 Algebra", "marks": 6, "solutionImage": "solutions/m2-q30.jpg"}]$json$::jsonb)
on conflict (id) do update set title = excluded.title, minutes = excluded.minutes,
  total = excluded.total, is_public = false, questions = excluded.questions;

insert into public.mocks (id, title, minutes, total, is_public, questions)
values ('crit2', 'Critical Thinking & PS Mock 2', 60, 30, false,
$json$[{"passage": "A manufacturer wishes to make an open-topped box out of the piece of cardboard shown below by", "image": "images/crit2-q1.png", "alt": "Cardboard net: a 60 cm by 60 cm square with a 5 cm by 5 cm square cut out of each corner, to be folded into an open-topped box.", "large": true, "q": "What is the volume of this box in cubic centimetres?", "options": ["1 600", "2 400", "8 000", "10 125", "12 500"], "answer": 4, "topic": "PS Finding Procedures", "solution": "The two labelled overall dimensions are 60 cm in this version. Each corner cut-out is 5 cm by 5 cm, so folding raises sides 5 cm high. The base loses a 5 cm strip at both ends of each dimension: 60 - 5 - 5 = 50 cm by 50 cm.\nThe volume is therefore 50 × 50 × 5 = 12,500 cubic centimetres, option E. A-D do not equal the product of the folded box's three internal dimensions. The overall cardboard width is not the base width after folding, and the side height comes from the cut-out size. The outline is the same net as the source; only the two overall length labels have changed from 50 to 60 cm."}, {"passage": "The petrol tank of Maya's car holds 50 litres of petrol. A warning light comes on when only 5 litres are left. She always fills it as soon as she can after the warning light comes on. The car travels 100km on 8 litres of petrol. Last time she put petrol in, which she was able to do immediately after the light came on, she only had $6 with her so she spent it all on fuel at 60c per litre. She then drove 50km and saw a new garage offering petrol at 50c per litre - an offer too good to miss. She filled the tank completely and paid with her credit card.", "q": "How much did it cost?", "options": ["$ 15.50", "$ 17.50", "$ 19.50", "$ 22.50", "$ 24.50"], "answer": 2, "topic": "PS Finding Procedures", "solution": "The first refill begins with 5 litres still in the tank. Spending $6 at $0.60 per litre buys 10 litres, leaving 15 litres altogether. The 50 km drive uses half of the stated 100 km consumption: 8/2 = 4 litres. Maya therefore reaches the new garage with 15 - 4 = 11 litres.\nTo fill a 50-litre tank she must buy 50 - 11 = 39 litres. At $0.50 per litre, this costs 39 × $0.50 = $19.50, option C. A, B, D and E do not match the fuel actually needed at the second garage. The question asks for that second purchase, not the first $6 or the combined amount spent at both garages. The warning reserve must be included in the fuel already present."}, {"passage": "We need to accept flooding as a regular occurrence in the Norland. Statistics show that days of ‘extreme rain’ (very heavy rainfall) have become more common since 1970, moving from one in a hundred days on average in the 1970s to one in seventy days in 2016. The apparent trend mirrors increases in extreme rain seen in other parts of the world. Countries such as Aruna and Belora expect and prepare for this, but in the Norland we have to change our thinking and plan our infrastructure to cope with it. The damage caused to homes and businesses as well as the risk of injury and death through flooding are very significant. Scientists say that, as the world has warmed by 0.7 °C, the atmosphere is able to hold 4% more moisture, which means more potential rain.", "q": "Which one of the following best expresses the main conclusion of the argument in the above passage?", "options": ["The Norland has been underprepared for the effects of flooding.", "The Norland could learn from countries such as Aruna and Belora about flood defences.", "Global warming could be halted if there was political will.", "The Norland must plan its infrastructure to deal with a high risk of flooding.", "The world temperature will continue to rise in the future."], "answer": 3, "topic": "CT Summarising the Main Conclusion", "solution": "The practical recommendation is that Norland should plan its infrastructure for a high flood risk: D. More frequent extreme rain, comparisons with countries that prepare for it, serious damage and additional atmospheric moisture are offered as reasons. The opening call to accept regular flooding supports this need to plan.\nA looks backward at preparedness rather than stating the future action urged. B suggests learning from other countries, which is narrower than the recommendation and not its main point. C introduces political will and halting warming, neither of which is argued. E predicts continuing temperature rises beyond the information supplied. Locate the policy conclusion supported by all the evidence rather than selecting a plausible related observation."}, {"passage": "According to a recent survey, many people believe that about a quarter of the population will become victims of a violent crime in the next year, whereas crime statistics show that it is only about 1 per cent. Furthermore, those with the greatest fear of crime, namely the elderly, are the least likely to be affected (since most victims are young men). The increasing number of television programmes which show re-enactments of crimes add to people's fears about violent crime by making it seem more common than it is. It is time that we stopped making such programmes.", "q": "Which one of the following, if true, would most weaken the above argument?", "options": ["TV crime re-enactments are made much more realistic than they used to be.", "Most elderly people are unaware of the statistics of violent crime.", "Some types of violent crime have declined over the last few years.", "The elderly are the group least likely to watch crime re-enactments on television.", "The figures on the amount of violent crime vary from area to area."], "answer": 3, "topic": "CT Assessing the Impact of Additional Evidence", "solution": "The proposed cause of exaggerated fear is watching crime reconstructions. D challenges this explanation by showing that the most fearful group has the lowest exposure to the alleged cause. This does not prove that programmes never affect fear, but it weakens their ability to explain the pattern used in the argument.\nA could increase the programmes' impact rather than weaken it. B is compatible with exaggerated fears because people lack statistical information. C says some crime has declined, which does not challenge the asserted media effect. E describes regional variation, but does not show that the comparison of fear and exposure is wrong. The best weakener is the option that most directly contests the proposed link, not merely another fact about crime."}, {"passage": "Aster Haulage pays dividends to its shareholders every six months. Bright Ball Bearings pays its shareholders every eight months and Kenton Chemists pays every eighteen months. In January 1992 all three companies paid me a dividend.", "q": "In what month and year did this next happen?", "options": ["July 1993", "January 1994", "July 1997", "January 1998", "January 2004"], "answer": 3, "topic": "PS Finding Procedures", "solution": "Joint payments recur after a whole number of each company's payment interval. Find the least common multiple of 6, 8 and 18 months. With factors 6 = 2 × 3, 8 = 8 and 18 = 2 × 9, the smallest shared interval is 8 × 9 = 72 months.\nSeventy-two months is six years. From January 1992, the next joint payment is January 1998: D. A and B are too soon; C is only 66 months later and does not fit all intervals. E is a later common payment but not the next one. The company names and all offered dates have been shifted consistently from the source, while the interval calculation remains unchanged."}, {"passage": "We are all becoming used to warnings of a shortage of science, technology, engineering and mathematics (STEM) recruits. In a world increasingly dominated by careers that involve these fields, organisations and politicians repeatedly state that we really must train more of these people to secure our prosperity. But STEM training is not the only answer: anecdotal evidence shows that the STEM employees who do best are those most skilled in thinking and communicating. Instead of looking to produce scientists or engineers, we should focus on turning out agile minds. The ability to process, synthesise and communicate information efficiently is the premium skill of the future.", "q": "Which one of the following best expresses the flaw in the argument above?", "options": ["It assumes that being agile-minded cannot be taught.", "It ignores the fact that STEM courses are growing in popularity.", "It fails to use comparative data from other countries.", "It assumes that agile minds are equally effective with or without STEM training.", "It ignores the views of STEM employers."], "answer": 3, "topic": "CT Detecting Reasoning Errors", "solution": "The evidence concerns employees who have STEM expertise and, among them, the additional advantage of thinking and communication skills. The conclusion proposes agile minds instead of technical training. D identifies the unsupported assumption that those skills would be equally effective after removing the technical expertise present in the examples. The evidence could support combining the two forms of training, not replacing one with the other.\nA is contrary to the proposal to develop agile minds; the argument does not assume they cannot be taught. B concerns popularity, not effectiveness. C requests a comparison that is not necessary to reveal the flaw. E is inaccurate because the passage does refer to what organisations and employers need. The key error is treating complementary attributes as interchangeable substitutes."}, {"passage": "More than twelve years after the ban on fishing for cod off Norland’s Atlantic coast, there is almost no sign of fish stocks getting back to normal as they were expected to do. Fisheries experts now think they know why. ‘We have learnt,’ says a chief science adviser, ‘that when fish numbers get very low the cod reproduce far less successfully than they do when the stocks are healthy, and if you predict recovery times based on healthy stocks you will be over-optimistic.’ Belora has also been heavily over-fishing. So, if the Norlandic experts are right, it is already too late to save Belora’s cod stocks from a similar fate.", "q": "Which of the following is an underlying assumption of the above argument?", "options": ["Belora is planning to impose a ban on cod fishing.", "The cod in Beloran waters breed in a similar way to those in Norlandic waters.", "Fish stocks will not recover in the next twelve years.", "A ban on fishing is not the answer to falling fish stocks.", "The Norlandic experts are right about the reasons for the slow recovery of fish stocks."], "answer": 1, "topic": "CT Identifying an Assumption", "solution": "The forecast applies an explanation for slow cod recovery in Norland to stocks in Belora. B is necessary: the relevant breeding response must be similar across those populations. If Beloran cod reproduced successfully even at low population levels, the Norlandic explanation would not support the prediction.\nA says Belora plans a ban, which is not needed to transfer the breeding explanation. C is a specific forecast about twelve years, not a bridge between populations. D makes a broad judgement against bans. E is not an additional assumption: the conclusion is explicitly conditional on the experts being right. A conditional argument can ask what follows if a claim is true without independently assuming the claim has been proved."}, {"passage": "There is a tendency to think that carnivores, given their precarious place at the top of the food chain, are the most at risk from extinction. Yet over the course of history it is likely that the opposite has been the case. Herbivores are often more specialist - evolved to suit a particular environment, to eat a particular plant. Carnivores, on the other hand, have tended to retain a more general set of attributes: teeth that could cut as well as chew; physical agility and acute senses, making them less vulnerable to changes in environment. After all, meat remains meat through even the most dramatic of environmental upheavals; whereas grassland might be converted to forest - with serious consequences for the herbivores that are grazing specialists.", "q": "Which one of the following best expresses the conclusion of the above argument?", "options": ["Herbivores are more threatened by environmental changes than carnivores.", "It is natural to think that carnivores are more at risk of extinction than herbivores.", "Herbivores are more at risk of extinction than carnivores.", "Carnivores are better at adapting to changes in environment than herbivores.", "Carnivores’ success is mostly down to their having more general adaptions than herbivores."], "answer": 2, "topic": "CT Summarising the Main Conclusion", "solution": "The passage begins by opposing the assumption that carnivores are most at risk and argues that, historically, herbivores are likely to have been more vulnerable. C expresses that main comparison about extinction risk. The specialists-versus-generalists contrast and the grassland example provide reasons for it.\nA and D concern vulnerability or adaptation to environmental change. These are supporting claims explaining the proposed difference in extinction risk, not the main conclusion. B states the view the author challenges. E attributes carnivore success to general adaptations, another explanatory point rather than the central claim about comparative extinction risk. The main conclusion is the claim the biological details are used to support; it need not be the final sentence."}, {"passage": "An artist has three 150ml tubes of paint: one red, one yellow and one blue. Mixing equal quantities of red and yellow gives orange, mixing equal quantities of red and blue gives purple, mixing equal quantities of yellow and blue gives green, and mixing equal quantities of red, yellow and blue gives brown. The design of a small mural needs 30% of brown and 20% of red, as well as 10% of each of blue, yellow, orange, purple and green.", "q": "If after painting the mural the artist has 30ml of paint left in the red tube, how much blue paint will be left?", "options": ["45ml", "60ml", "75ml", "90ml", "105ml"], "answer": 1, "topic": "PS Finding Procedures", "solution": "Track the original colour used to make each final colour. Let the total amount painted be T. Red is used in direct red paint (20% of T), one third of brown (10%), half of orange (5%) and half of purple (5%). Thus red consumption is 40% of T.\nThe red tube starts with 150 ml and has 30 ml left, so 120 ml was used. Hence T = 120/0.40 = 300 ml. Blue is used directly (10%), in brown (10%), in purple (5%) and in green (5%), totalling 30% of T = 90 ml. Blue remaining is 150 - 90 = 60 ml: B. A and C-E do not account for blue in every relevant mixture. The percentages refer to final mural colours, not simply to the three starting tubes."}, {"passage": "Merlan City has just installed a new tram system. Several artists have been asked to come up with a map of the system which, whilst it may not show the exact relative positions of the stations, shows the connections between them correctly.\nThe five maps are shown below (the names of the stations are not marked).\nFour of the artists drew possible maps, but the fifth got the connections wrong.", "image": "images/crit2-q10.png", "alt": "Five maps labelled A to E of a tram network, each drawn as dots joined by lines.", "large": true, "q": "Which map below is based on incorrect connections?", "options": ["Map A", "Map B", "Map C", "Map D", "Map E"], "answer": 2, "topic": "PS Identifying Similarity", "solution": "Distances, angles and the shape of a drawn route may change, but the number of connections at each station cannot. In A, B, D and E, each station has either two or three connections; each of those maps has two degree-2 stations and four degree-3 stations. In C, the central lower station has four connections: to the top, left, right and lower-right stations.\nThat four-way junction has no counterpart in the other maps, so C must be the incorrect map. Counting the incident routes at the marked dots is enough; a bend in a line does not create another station. A, B, D and E are alternative layouts of the same connections. This explanation independently counts the actual figure rather than copying the worked book's station-count wording."}, {"passage": "Research in Norland suggests that people are more likely to recognise the stars of soap operas than world leaders. A sample of 500 people were given photographs of three world leaders and three 'soap stars'. Only 30% were able to identify the world leaders, such as the Beloran president Alexei Petrov, yet 80% were able to identify 'soap stars' such as Elena Marlow, one of the main actors in the Norlandn series 'Neighbours'.", "q": "Which of the following is a conclusion that can be drawn from the above passage?", "options": ["Some people in the sample recognised both the soap opera stars and the world leaders.", "Some people in the sample recognised neither the soap opera stars nor the world leaders.", "At least 80% of those in the sample must regularly watch soap operas.", "A person who recognises soap opera stars is more likely to recognise world leaders.", "A person who recognises world leaders is less likely to recognise soap opera stars."], "answer": 0, "topic": "CT Drawing a Conclusion", "solution": "Thirty per cent of 500 is 150 people, and 80% is 400 people. If the groups were disjoint they would contain 550 people, more than the whole sample. At least 50 people must therefore be in both groups. A follows.\nB is possible but not guaranteed: the two groups could together cover the whole sample. C infers regular viewing from recognition; recognition may come from publicity or other exposure. D and E compare conditional recognition rates, which depend on how the overlap is distributed. The overlap is known to be at least 50 but not known exactly, so neither comparison follows. The numerical principle is that two subsets whose sizes sum to more than the whole must overlap."}, {"passage": "In the country of Ardania the postage charge for sending a letter is calculated according to the following formula: 20 cents per 50 square centimetres of envelope area plus 32 cents per 40 grams of weight. All measurements of area and weight are rounded up to the next multiples of 50 square centimetres and 40 grams before calculation. Mira has a letter weighing 135 grams in a 20 cm by 12 cm rectangular envelope that she wants to send.", "q": "What will the postage charge be for Mira’s letter?", "options": ["$1.48", "$1.68", "$1.76", "$1.96", "$2.28"], "answer": 4, "topic": "PS Finding Procedures", "solution": "The envelope area is 20 × 12 = 240 square centimetres. Round it up to 250, the next multiple of 50, giving five chargeable area units. At 20 cents each, this contributes 100 cents. Mira's 135 g letter is rounded up to 160 g, the next multiple of 40, giving four weight units. At 32 cents each, these contribute 128 cents.\nTotal postage is 100 + 128 = 228 cents, or $2.28: E. A-D are below the amount required by the two rounded charges. The two rounding operations are separate and must occur before costing; using 135/40 or 240/50 as fractional charging units would undercharge. The changed weight remains in the same rounding band as the source question."}, {"passage": "Hasan lives at the top and Jamil lives at the bottom of a hill 6 km long. Each Saturday they meet at a bench on the hill somewhere between their houses. They find that, if they both leave their houses at 10 am, they arrive at the bench at the same time. They both walk at 2 km/hr uphill and 6 km/hr downhill. After talking for an hour they each return home.", "q": "How much earlier does Jamil arrive home than Hasan?", "options": ["They arrive at the same time", "Jamil arrives ½ hour before Hasan", "Jamil arrives 1 hour before Hasan", "Jamil arrives 1 ½ hours before Hasan", "Jamil arrives 2 hours before Hasan"], "answer": 4, "topic": "PS Finding Procedures", "solution": "Hasan starts at the top and walks downhill at 6 km/h; Jamil starts at the bottom and walks uphill at 2 km/h. Together they close the 6 km gap at 8 km/h, meeting after 6/8 = 0.75 hour. Hasan has travelled 4.5 km and Jamil 1.5 km.\nThey talk for the same hour, so it cancels from the difference in homecoming times. Hasan must return uphill for 4.5 km at 2 km/h, taking 2.25 hours. Jamil returns downhill for 1.5 km at 6 km/h, taking 0.25 hour. Jamil arrives 2 hours earlier: E. They meet simultaneously, but their homeward routes differ in both distance and speed. A-D do not match the two-hour difference."}, {"passage": "Recorded crime figures - the figures which police authorities produce - have always been a poor way to identify crime trends. They are really a measure of police activity and priorities. A big operation to tackle knife crime, for instance, may uncover and record many more offences involving knives: it does not mean knife crime is rising. Added to that, there is an inbuilt temptation for police officers to ‘adjust’ their crime figures when targets need to be met. As with all recorded activity or performance data, there is always a risk of inaccuracy, confusion and fraud. A much more reliable measure of crime is the Crime Survey of Norland and Aruna which produces figures by asking people if they have been victims of crime.", "q": "Which one of the following is a conclusion that can be drawn from the above passage?", "options": ["The police regularly prioritise the tackling of crimes which help them meet their targets.", "The police care more about meeting targets than they do about tackling crime.", "Much less crime takes place than police figures tend to indicate.", "Victims of crime fear retaliation from criminals if they report them to the police.", "To find out whether crime levels are increasing we should survey people’s experience of crime."], "answer": 4, "topic": "CT Drawing a Conclusion", "solution": "The passage argues that recorded figures can reflect police activity, priorities and target pressures rather than crime levels alone. It contrasts them with a survey of people's experience, described as more reliable. E is the supported practical conclusion about how to investigate changing crime levels.\nA says police regularly choose crimes to meet targets, stronger and more specific than the passage establishes. B ranks police motives, which is not demonstrated. C assumes the distortion is always upward; the passage describes risks of inaccurate recording without fixing their overall direction. D supplies a possible reason for under-reporting that is not stated. E follows the recommendation implicit in the comparison of the two methods without adding an unproved claim about motives or the amount of crime."}, {"passage": "A three-month study of major producers of ivory products showed that worldwide demand for elephant tusks for ivory had fallen sharply. Consequently it is safe to assume that there will be a general decline in elephant poaching.", "q": "Which one of the following, if true, would most weaken the above argument?", "options": ["There are far fewer elephants than there were ten years ago, so poachers are finding it increasingly difficult to make a living from the ivory trade.", "Poachers now use high-powered rifles which make it far easier for them to kill larger numbers of elephants than was possible in the past.", "The worldwide demand for ivory fluctuates considerably at certain times of the year, so poachers stockpile ivory to sell when the market improves.", "More and more synthetic materials are being used as substitutes for ivory in the construction of such things as piano keys and billiard balls.", "The worldwide demand for ivory has been falling consistently for the last twenty years and many ivory poachers have found alternative sources of income."], "answer": 2, "topic": "CT Assessing the Impact of Additional Evidence", "solution": "The conclusion predicts a general decline in poaching from a short study of reduced demand. C challenges whether that period represents the longer-term market and explains why collectors might continue: they can stockpile ivory until demand improves. A temporary fall therefore need not lead to a general reduction in killing.\nA suggests the trade is harder to sustain and does not supply the same reason to continue at present levels. B describes more effective hunting equipment, but does not explain why a fall in demand would cease to discourage poaching. D supports reduced demand through substitutes. E supplies evidence of a sustained decline and alternative livelihoods, strengthening rather than weakening the prediction. The most relevant challenge targets the move from a short observation to a general trend."}, {"passage": "The Richter Scale is used to measure the strength of earthquakes. It has the property that an increase of one unit on the scale represents a tenfold increase in the strength of the quake. Three earthquakes have the following values on the Richter Scale: X : 3.0 Y : 4.0 Z : 5.0", "q": "Which one of the following statements about their relative strengths is true?", "options": ["X is one-tenth the strength of Y and one-twentieth the strength of Z.", "X is one-tenth the strength of Y and one-hundredth the strength of Z.", "X is one-tenth the strength of Y and one-thousandth the strength of Z.", "Z is twice as strong as X and Y is one-and-a-half times as strong as X.", "Z is one-tenth stronger than Y which is one-tenth stronger than X."], "answer": 1, "topic": "PS Finding Procedures", "solution": "Each one-unit increase means multiplying strength by ten. Y, at 4.0, is therefore ten times X, at 3.0. Z, at 5.0, is another factor of ten above Y, so it is 100 times X. Equivalently, X is one tenth of Y and one hundredth of Z: B.\nA uses a factor of twenty instead of one hundred for two steps. C uses one thousand, which would require three unit steps. D treats the scale values as directly proportional to strength, contrary to the stated tenfold rule. E confuses ten times with one tenth more. Changing all three readings upward by one unit changes absolute strengths by a common factor but leaves their relative ratios unchanged."}, {"passage": "High street stores should not be able to sell financial products, because consumers should not be misled into buying products they may not need by staff who do not understand what they are selling. Financial products require an understanding of financial services, and very few high street retailers have members of staff in store who can fully explain the benefits and disadvantages of the financial products being sold.", "q": "Which one of the following, if true, most strengthens the above argument?", "options": ["Many high street stores have been fined by the financial regulator for mis-selling financial products.", "Many stores offer incentives to customers to encourage them to sign up for store cards.", "Consumers are supplied with full details of the terms and conditions for all financial products that they sign up for.", "Many people do not understand the financial products they purchase yet still benefit from them.", "Most people do not read the terms and conditions of products and services that they sign up to."], "answer": 0, "topic": "CT Assessing the Impact of Additional Evidence", "solution": "The argument objects to the sale of financial products by staff unable to explain them because customers may consequently be misled into unsuitable purchases. A supplies evidence that the feared harm has actually occurred in many stores: regulatory penalties for mis-selling. This strengthens the case for the restriction.\nB shows incentives to acquire store cards, but does not directly show staff misunderstanding or unsuitable sales. C offers a possible safeguard through full written information and could count against the worry. D shows that limited customer understanding can coexist with benefit, also reducing the force of the argument. E indicates failure to read terms, but is less direct evidence of the particular mis-selling risk than actual penalties. A supports the proposed harm, rather than merely discussing financial products."}, {"passage": "The cog sizes and chain length on a bicycle are designed to even out wear, so that the same hole in the chain does not encounter the same tooth on the cog in every revolution. The chain wheel (front cog) of a particular bicycle has 48 teeth, the rear cog has 18 teeth and the chain has 90 holes.", "q": "How many revolutions must the front cog do before the chain and both cogs are back in exactly the same relative positions (i.e. the same holes are encountering the same teeth on both cogs)?", "options": ["5", "8", "15", "20", "30"], "answer": 2, "topic": "PS Finding Procedures", "solution": "For all three components to regain their original relative positions, the number of chain links passing must be a whole multiple of the 48 front teeth, 18 rear teeth and 90 chain holes. The least common multiple is 720: 48 = 16 × 3, 18 = 2 × 9 and 90 = 2 × 9 × 5, so the combined requirement is 16 × 9 × 5.\nThe front cog makes 720/48 = 15 revolutions, giving C. Check: the rear makes 720/18 = 40 revolutions and the chain makes 720/90 = 8 circuits. A, B and D do not restore all components; E would restore them but is not the first return. The relevant common quantity is links moved, not the three rotation counts being equal."}, {"passage": "The table below records the scores of 100 games in a football league. The entries show the number of games in which the teams have scored the number of goals shown in the headings (for example there were 10 games in which the home team scored 2 goals and the away team scored 1 goal).", "table": {"head": ["Goals scored by the away team / Goals scored by the home team", "0", "1", "2", "3", "4 or more"], "rows": [["0", "12", "8", "8", "4", "4"], ["1", "3", "7", "10", "3", "2"], ["2", "5", "7", "8", "3", "2"], ["3", "5", "3", "2", "0", "0"], ["4 or more", "3", "1", "0", "0", "0"]]}, "q": "In how many games were 3 or more goals scored?", "options": ["0", "14", "18", "31", "57"], "answer": 4, "topic": "PS Relevant Selection", "solution": "Count the complement: games with fewer than three total goals. Zero total goals occurs in the 0-0 cell: 12 games. One total goal occurs in 1-0 and 0-1: 8 + 3 = 11 games. Two total goals occurs in 2-0, 1-1 and 0-2: 8 + 7 + 5 = 20 games.\nThus 12 + 11 + 20 = 43 games had fewer than three goals, leaving 100 - 43 = 57 with at least three. E is correct. Do not count only cells where either team individually scored at least three: a 2-1 or 1-2 result also qualifies. Every cell with '4 or more' for either team qualifies automatically, so the grouped heading creates no ambiguity."}, {"passage": "Many people imagine that large country houses in the eighteenth century had smooth lawns. But in those days there was no way of killing wild plants and weeds and, with the lawnmower not invented, the only method of cutting a lawn was by teams of gardeners with hand scythes; today's weed-free close cuts were unthinkable. Given this, lawns must have been like flowery meadows.", "q": "Which one of the following best expresses the main conclusion of the argument above?", "options": ["Modern lawns are kept smooth only with the use of weedkillers and lawnmowers.", "The upkeep of eighteenth century lawns required the employment of large numbers of gardeners.", "In the eighteenth century, lawns were not smooth but more like flowery meadows.", "It is more natural to have a lawn like a flowery meadow than one kept in smooth condition.", "Modern lawns would seem boring to a person from the eighteenth century."], "answer": 2, "topic": "CT Summarising the Main Conclusion", "solution": "C is the conclusion: eighteenth-century lawns must have resembled flowery meadows rather than today's smooth lawns. The inability to kill weeds and the reliance on hand scythes are the reasons supporting it.\nA concerns how modern lawns are maintained and is not the historical conclusion the passage is trying to establish. B is a supporting detail about the workforce rather than the overall description inferred. D introduces a judgement about what is natural, which the passage does not argue. E predicts an eighteenth-century person's taste and is unsupported. The word 'Given this' signals that the final sentence is being inferred from the earlier practical limitations. Select the historical inference rather than an attractive comment about lawns."}, {"passage": "The Gadget Manufacturing Company has five Executive Sales Consultants each of which is responsible for one part of the country. They have sales targets for each quarter of the year which depend on the potential market in the area and seasonal fluctuations in business. The targets and performance (+ for better than target, - for worse than target) are shown in the table below.", "table": {"head": ["Name / Region", "Sales $000", "Quarter 1", "Quarter 2", "Quarter 3", "Quarter 4", "Year"], "rows": [["Baker / North", "Target", "800", "900", "750", "600", "3050"], ["", "Performance", "+100", "+150", "+50", "+450", "+750"], ["Grant / East", "Target", "1000", "1200", "900", "800", "3900"], ["", "Performance", "-100", "+350", "-150", "+250", "+350"], ["Ward / Midlands", "Target", "1200", "1600", "1050", "900", "4450"], ["", "Performance", "+100", "-150", "+50", "+200", "+200"], ["Blake / West", "Target", "900", "1050", "800", "650", "3400"], ["", "Performance", "+200", "+150", "+350", "+100", "+800"], ["Gray / South", "Target", "1300", "1500", "1200", "1000", "5000"], ["", "Performance", "-150", "-100", "+200", "+150", "+100"]]}, "q": "Who recorded the biggest sales total for any single quarter during the year?", "options": ["Baker", "Grant", "Ward", "Blake", "Gray"], "answer": 1, "topic": "PS Relevant Selection", "solution": "Performance entries are amounts above or below target, not the sales totals themselves. Add each quarter's performance to its target. Baker's actual quarterly sales are 900, 1050, 800 and 1050 thousand dollars. Grant's are 900, 1550, 750 and 1050. Ward's are 1300, 1450, 1100 and 1100. Blake's are 1100, 1200, 1150 and 750. Gray's are 1150, 1400, 1400 and 1150.\nThe greatest single-quarter total is Grant's 1550 thousand in Quarter 2, so B is correct. The largest performance surplus alone would not answer the question, because targets differ. Likewise, annual totals are irrelevant to the requested maximum in one quarter. The best quarter for each of A, C, D and E remains below 1550."}, {"passage": "Researchers have discovered the first physical evidence of structural brain differences that distinguish early risers from people who like to stay up late. Around 12 per cent of people qualify as ‘morning people’ or ‘larks’, and a further 18 per cent are ‘night owls’ - with the rest of us falling somewhere in between. The brain differences might help to explain why ‘night owls’ seem to be at greater risk of depression than ‘larks’. Brain scans have shown ‘night owls’ have a lower quality of white matter (tissue largely comprised of fatty insulating material that speeds up the transmission of nerve signals) in areas of the brain associated with depression. ‘Night owls’ should try to adjust their sleep patterns if they wish to avoid mental health problems.", "q": "Which one of the following best expresses the flaw in the above argument?", "options": ["It fails to refer to the brains of those who fall between ‘lark’ and ‘night owl’ types.", "It ignores the fact that depression is very common in the population.", "It assumes that changing one’s sleep pattern will cause a change in the quality of white matter.", "It implies that ‘night owls’ would wish to change their sleep patterns.", "It associates depression with other mental health problems."], "answer": 2, "topic": "CT Detecting Reasoning Errors", "solution": "C identifies the unsupported intervention claim. The evidence reports an association between sleep type, white-matter quality and depression risk. It does not show that deliberately changing sleep times changes white matter or removes the associated risk. The direction of causation, or a common underlying cause, has not been established.\nA points to the intermediate group, but the argument about changing the habits of night owls could still be assessed without that group's details. B states a general fact about prevalence rather than challenging the causal step. D is unnecessary: the advice is conditional on wishing to avoid problems. E concerns the broader wording 'mental health problems', but C targets the essential basis of the recommendation. Association alone does not establish the benefit of changing one associated feature."}, {"passage": "A youth club ran a “complete the puzzle against the clock” competition last Saturday. Teams had to complete a variety of puzzles and were awarded points determined by how long it took them to complete each puzzle:\nLess than 10 minutes = 9 points\nBetween 10 and 20 minutes = 5 points\nBetween 20 and 30 minutes = 3 points\nAny team failing to complete a puzzle within 30 minutes had 2 points taken off their score.\nAt the half-way stage of the competition, when all teams had completed four puzzles, the total scores were displayed on a score-board as shown below:", "table": {"head": ["Team Name", "Score"], "rows": [["Cryptics", "22"], ["Mosaics", "21"], ["Cubists", "24"], ["Singles", "23"], ["Tilework", "25"]]}, "passageAfter": "One of the teams has been credited with a score which is not possible from four puzzles on the given scoring system.", "q": "Which team has a score which has been wrongly calculated (i.e. could not possibly have been scored at this stage)?", "options": ["Cryptics", "Mosaics", "Cubists", "Singles", "Tilework"], "answer": 3, "topic": "PS Finding Procedures", "solution": "Each of four puzzle results contributes one of 9, 5, 3 or -2 points. Four of the listed totals can be exhibited directly: Cryptics' 22 = 9 + 5 + 5 + 3; Mosaics' 21 = 9 + 9 + 5 - 2; Cubists' 24 = 9 + 9 + 3 + 3; Tilework's 25 = 9 + 9 + 9 - 2.\nSingles' 23 is impossible, so D is correct. To check systematically, suppose k puzzles scored -2. The other 4-k scores are odd, so an odd total requires k odd: 1 or 3. With k = 3 the maximum is 9 - 6 = 3. With k = 1, the three positive scores must total 25; but their possible sums include 27, 23, 21 and lower values, not 25. This also avoids assuming every puzzle was completed successfully."}, {"passage": "Riverford Swimming Pool charges £2 per session for adults and £1 for children. Also available is a Family Swimcard. At a cost of £50, the Family Swimcard allows unlimited use of the pool for one year for 2 adults and up to 3 children. For larger families, every additional child must pay half the children's rate each time. Mr and Mrs Rana and their 4 children are keen swimmers. They used their Swimcard when the family went swimming 40 times last year.", "q": "How much did the Swimcard save the Rana family last year?", "options": ["£ 50", "£ 190", "£ 230", "£ 250", "£ 270"], "answer": 3, "topic": "PS Finding Procedures", "solution": "Without a card, one visit by two adults and four children costs 2 × £2 + 4 × £1 = £8. Forty visits would cost 40 × £8 = £320. With the card, the fixed annual charge is £50. Only three children are included, so the fourth pays half the normal child rate, £0.50, on each visit: 40 × £0.50 = £20. Card-based expenditure is £50 + £20 = £70. The saving is £320 - £70 = £250, option D. E omits the fourth child's £20 charge. A-C do not subtract the complete card-based cost from normal admission. The card's purchase price is part of the expense, not itself the amount saved."}, {"passage": "On the island of Nerra tax is paid as follows: No tax on the first $5000 of income, then10% on the next $10000 plus 25% on the remainder.", "q": "How much tax is paid on an annual income of $45000?", "options": ["$4500", "$8500", "$9000", "$11250", "$12750"], "answer": 1, "topic": "PS Finding Procedures", "solution": "Separate the income into tax bands. The first $5000 is untaxed. The next $10,000 incurs 10%, giving $1000. Income above $15,000 is $45,000 - $15,000 = $30,000. At 25%, that contributes $7500. Total tax is $1000 + $7500 = $8500, option B.\nA applies 10% to all income, ignoring the bands. D applies 25% to the whole income, including the untaxed and lower-rate portions. C and E do not equal the sum of the stated band charges. A marginal tax rate applies only to the amount within its band; entering the highest band does not retrospectively change the rate on earlier income."}, {"passage": "If drivers were made to pay for road use according to the amount of time they spent on the road, they would drive more dangerously. Experiments were conducted with volunteers using a driving simulator. In the first experiment, the volunteers were charged for time spent driving below 12mph in order to see how people coped with trying to avoid congestion. In the second experiment, they were charged for the time spent in a particular area. The results were alarming. The volunteers in the first experiment jumped many red lights in an attempt to keep their speed up. Those in the second frequently broke the speed limit, and overtook in dangerous situations. In the interests of road safety, we should not introduce such payment schemes.", "q": "Which one of the following is an underlying assumption of the above argument?", "options": ["Driving simulators are a reliable guide to real-life driving.", "We need to do more experiments on schemes of payment for road use.", "More people should practise their driving skills using a simulator.", "Schemes involving payment for road use will not solve the problem of road congestion.", "Road congestion could be solved in ways other than payment for road-use schemes."], "answer": 0, "topic": "CT Identifying an Assumption", "solution": "The conclusion concerns what drivers would do on real roads, while the evidence concerns choices made in driving simulators. A is the assumption that lets the findings support the real-world prediction. If simulator behaviour were not a reliable guide, the dangerous actions observed would not justify the stated road-safety conclusion.\nB calls for more research but is not a premise needed to make this inference. C is a recommendation about practice. D concerns whether charging reduces congestion, whereas the argument rejects it on safety grounds even if it might reduce congestion. E proposes the availability of alternatives, which does not establish the harmful effect of the tested schemes. The essential gap is between the experiment's setting and the setting of the policy."}, {"passage": "There have been various proposals over the years for a system of decimal time. Under one system the day would remain the same length of time as it is at present, but would be the basic unit of time, divided into 10 decidays each made up of 100 millidays. Clocks would show the time in decidays and millidays instead of hours and minutes. Midday would be 0:00 and midnight would, therefore, be 5:00.", "q": "If this system were ever to be introduced and a new-style digital clock was compared with an old-style digital clock, what would the old clock read when the new clock showed 1:75?", "options": ["14:52", "15:02", "16:12", "16:20", "16:40"], "answer": 2, "topic": "PS Finding Procedures", "solution": "One deciday is one tenth of a 24-hour day: 2.4 hours, or 144 minutes. The display 1:75 means 1 deciday plus 75/100 of a deciday, so 1.75 decidays. This is 1.75 × 144 = 252 ordinary minutes.\nTwo hundred fifty-two minutes is 4 hours 12 minutes. The new clock starts at noon, so adding that interval gives 16:12 on the ordinary clock: C. A, B, D and E correspond to different elapsed intervals. In particular, the 75 millidays must not be treated as 75 ordinary minutes. The unit named a milliday here is one thousandth of a day because there are 10 × 100 of them per day."}, {"passage": "It is both morally and economically wrong for the Government to give implicit approval to an employment system that lands the state with a huge bill to top up the incomes of the lowest earners. The holes in millions of pay cheques are being plugged by in-work support to the tune of £5 bn a year. But why aren’t those who are profiting from their workers paying up? Why is the Government having to subsidise businesses who don’t pay their employees enough to live on? It is a question we need to answer and act on - fast. The cost of living is rising but wages are not. In the rush for profit, and for high pay at the top, too many companies have forgotten the basic moral imperative that employees be paid enough to live on.", "q": "Which one of the following is the best statement of the principle underlying the above argument?", "options": ["The Government is responsible for the employment system that leaves holes in millions of pay cheques.", "It is morally wrong of the Government to assist people on low incomes.", "High pay at the top end is responsible for low wages at the bottom end of the employment ladder.", "All pay should increase each year at the same rate as the cost of living.", "Every worker should be paid at least a living wage by those who profit from their work."], "answer": 4, "topic": "CT Applying Principles", "solution": "The argument objects to businesses relying on the state to supplement inadequate pay. It appeals to the obligation of those who profit from employees to pay enough for them to live. E states that principle directly.\nA identifies government responsibility for the system, but does not express the moral standard applied to employers. B objects to helping low-income people at all, which is not the claim; the complaint is about shifting an employer's responsibility to the state. C gives a proposed cause of low pay, not the principle. D requires all wages to rise with living costs, broader and different from a minimum living-wage requirement. The question asks for the rule underlying the judgement, not a statistic or a related pay policy."}, {"passage": "In order for it to be possible to rain, clouds must be present. The weather forecast is predicting clear skies, so there is no chance of rain.", "q": "Which one of the following most closely parallels the reasoning used in the above argument?", "options": ["The temperature in the fish tank must be at least 26°C for the fish to survive. The fish are all alive, therefore the temperature must be at least 26°C.", "Solar eclipses only occur at New Moon, when the Moon is between the Earth and the Sun. The new moon is not until next week, so there will be no Solar eclipse today.", "A scab will only form when platelets in the blood have clotted. If you do not have any scabs, you do not have platelets in your blood.", "When outside temperatures fall below 0°C household pipes are at risk of bursting. So at a temperature of -5°C all your household pipes will burst.", "Deciduous trees lose their leaves in the autumn. Autumn will be late this year, so trees will not lose their leaves until winter."], "answer": 1, "topic": "CT Matching Arguments", "solution": "The pattern is a necessary condition followed by its absence: rain requires clouds; no clouds; therefore no rain. B matches: a solar eclipse requires a new moon; no new moon today; therefore no solar eclipse today.\nA reasons forward from the occurrence of an outcome to its necessary condition, not from the condition's absence to the outcome's absence. C incorrectly moves from no scabs to no platelets, denying the outcome rather than the required condition. D turns a risk into a certainty. E makes an additional prediction from a shifted season instead of applying the same necessary-condition structure. You do not need specialist astronomy: the relevant eclipse rule is explicitly provided in B. Matching the logical direction is what matters."}, {"passage": "Political legitimacy, the moral right to use state power, can only be derived from the consent of the governed. So, in democracies that uphold this principle, regular elections are held to ensure that political power is legitimate. Therefore, in these cases, the more voters participate in elections, the more legitimate the democratic political system is.", "q": "Which one of the following is an assumption underlying the above argument?", "options": ["Electoral turnout is always higher in democratic political systems.", "Voting at elections implies consent to the political system as a whole.", "There is always a need for a government.", "The more people who vote, the more the common interests are met.", "Non-democratic political systems rely on coercion as a basis of state power."], "answer": 1, "topic": "CT Identifying an Assumption", "solution": "The argument moves from a rule about consent to a claim that higher voting participation means greater legitimacy. B supplies the link: participation must indicate consent to the political system as a whole. If voting expressed only a preference among candidates while withholding consent to the system, turnout would not measure the required consent.\nA compares democratic and other systems, which is irrelevant to the claim about changes in turnout within democracies. C concerns the need for government, not consent to a particular system. D concerns whether interests are met, which is not the stated basis of legitimacy. E describes coercion elsewhere, not what voting signifies here. The missing premise must connect the measured behaviour to the value the conclusion assigns it."}]$json$::jsonb)
